    n->count = 1;
    n->size = 1;
    n->left = NULL;
    n->right = NULL;
    return n;
}

static inline void update(Node* t) {
    if (t) {
        t->size = t->count + (t->left ? t->left->size : 0) + (t->right ? t->right->size : 0);
    }
}

static Node* rotate_right(Node* y) {
    Node* x = y->left;
    y->left = x->right;
    x->right = y;
    update(y);
    update(x);
    return x;
}

static Node* rotate_left(Node* x) {
    Node* y = x->right;
    x->right = y->left;
    y->left = x;
    update(x);
    update(y);
    return y;
}

static Node* insert(Node* t, long long key) {
    if (!t) return new_node(key);
    if (key == t->key) {
        t->count++;
        t->size++;
        return t;
    }
    if (key < t->key) {
        t->left = insert(t->left, key);
